import { LabelList, Line as RechartsLine, Dot, type DotProps } from "recharts";
import { useTheme } from "@theme";
import { clsx } from "clsx";
import { SVGTextElementAttributes } from "react";

import { IndividualLabel, LineProps } from "../chart.types";
import { useChart } from "../hooks/use-chart";
import { ChartClasses } from "../chart.styles";

interface IndividualDotProps extends DotProps {
  payload?: {
    label?: IndividualLabel;
    value?: number | string;
  };
}

const IndividualDot = (props: IndividualDotProps) => {
  const theme = useTheme();
  const { cx, cy, payload = {} } = props;
  const { label, value } = payload;

  if (!label || !cx || !cy) {
    return false;
  }

  const { text, position = "top" } = label;
  let x = cx;
  let y = cy;
  let textAnchor: "middle" | "start" | "end" = "middle";
  let dominantBaseline: SVGTextElementAttributes<SVGTextElement>["dominantBaseline"] = "auto";

  switch (position) {
    case "bottom":
      y += 8;
      dominantBaseline = "hanging";
      break;
    case "left":
      x -= 8;
      textAnchor = "end";
      dominantBaseline = "middle";
      break;
    case "right":
      x += 8;
      textAnchor = "start";
      dominantBaseline = "middle";
      break;
    case "top":
      y -= 8;
      dominantBaseline = "auto";
      break;
  }

  return (
    <>
      <Dot {...props} />
      <text
        className={ChartClasses.lineLabel}
        dominantBaseline={dominantBaseline}
        fill={theme.color.content.default}
        textAnchor={textAnchor}
        x={x}
        y={y}
      >
        {text || value}
      </text>
    </>
  );
};

const Line = ({ lineIndex = 0, showLineLabel: showLineLabelProp, ...props }: LineProps) => {
  const theme = useTheme();
  const { showLineLabels: showLineLabelsFromContext, numCategoricalColors } = useChart();

  const showLineLabels = showLineLabelProp ?? showLineLabelsFromContext;

  const lineProps: LineProps = { ...props };

  if (!props.stroke) {
    const colorKey = `${
      (lineIndex % numCategoricalColors) + 1
    }Default` as keyof typeof theme.color.data.categorical;
    lineProps.stroke = theme.color.data.categorical[colorKey];
  }

  if (!props.fill) {
    const colorKey = `${
      (lineIndex % numCategoricalColors) + 1
    }Default` as keyof typeof theme.color.data.categorical;
    lineProps.fill = theme.color.data.categorical[colorKey];
  }

  let labelChild: React.ReactNode;
  if (showLineLabels && showLineLabels !== "individual") {
    const position = typeof showLineLabels === "string" ? showLineLabels : "top";
    labelChild = (
      <LabelList
        className={ChartClasses.lineLabel}
        fill={theme.color.content.default}
        offset={8}
        position={position}
      />
    );
  }

  return (
    <RechartsLine
      dot={showLineLabels === "individual" ? <IndividualDot /> : !!showLineLabels}
      strokeWidth={3}
      {...lineProps}
      className={clsx(ChartClasses.line, lineProps.className)}
    >
      {labelChild}
    </RechartsLine>
  );
};

Line.displayName = "Line";

export default Line;
